import sys

def main():
    input = sys.stdin.read().splitlines()
    your_name = input[0]
    n = int(input[1])
    actions = input[2:]

    points = {'posted on': 15, 'commented on': 10, 'likes': 5}
    priority = {}

    for action in actions:
        parts = action.split()
        if parts[0] != your_name and parts[-1].strip("'s") != your_name:
            continue
        if parts[0] == your_name:
            name = parts[-1].strip("'s")
            action_type = ' '.join(parts[1:3])
        else:
            name = parts[0]
            action_type = ' '.join(parts[2:4])

        if name not in priority:
            priority[name] = 0
        priority[name] += points[action_type]

    result = sorted(priority.keys(), key=lambda x: (-priority[x], x))
    for name in result:
        print(name)

main()
